function itemsPerBudget(prices: number[], budgets: number[]): number[] {
  const sorted = [...prices].sort((x, y) => x - y);
  return budgets.map(budget => {
    let total = 0, count = 0;
    for (const p of sorted) {
      if (total + p > budget) break;
      total += p;
      count++;
    }
    return count;
  });
}

