    def itemsPerBudget(self, prices: List[int], budgets: List[int]) -> List[int]:
        s = sorted(prices)
        out = []
        for budget in budgets:
            total = count = 0
            for p in s:
                if total + p > budget:
                    break
                total += p
                count += 1
            out.append(count)
        return out

