function itemsPerBudget(prices: number[], budgets: number[]): number[] {
  const pre = [...prices].sort((x, y) => x - y);
  for (let i = 1; i < pre.length; i++) pre[i] += pre[i - 1];
  return budgets.map(budget => {
    // first index whose prefix sum exceeds the budget
    let lo = 0, hi = pre.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (pre[mid] <= budget) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  });
}

